use std::{fs,path::Path,collections::BTreeMap,fmt::Write};
use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-fused-top";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-27-fused-top";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){
 let r=Path::new(R);let d=Path::new(D);let full=r.join("performance-analysis.json").exists();let stage=if full{"performance"}else{"screen"};
 let a=read(r.join(format!("{stage}-analysis.json")));let screen=read(r.join("screen-analysis.json"));let protocol=read(r.join(stage).join("protocol.json"));
 for(p,h)in protocol["pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap(),"closing pin {p}");}
 let m=read("/tmp/zopro-grouping-module/production-source-manifest.json");for(p,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());}
 assert_eq!(hash("/tmp/zopro-grouping-module/native/candidate-sdk"),"03e1260e89068c2bec37a2471c34e93628a9f081903e1b7eee9cab9c306aaf3d");
 assert_eq!(read(r.join("native/core/tests.json"))["passed_tests"].as_array().unwrap().len(),110);
 let inventory=read(r.join("proof-inventory.json"));let mut proofs=0;for(p,h)in inventory.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());if p.ends_with(".proof"){assert_eq!(fs::metadata(p).unwrap().len(),164);proofs+=1;}}
 assert_eq!(proofs,a["independent_exports"].as_u64().unwrap());assert_eq!(inventory.as_object().unwrap().len(),proofs as usize*2);
 let close=json!({"status":"combined K/H top-digit SDK study closed","root":R,"source_originals":170,"unchanged_candidate_originals":168,"production_sources_checked_unchanged":170,"native_core_tests":110,"new_core_tests":1,"raw_tests":2,"cubic_tests":6,"field_source_and_qualification_inherited":true,"fresh_control_reused_unchanged":true,"SDK_requests":a["sdk_requests"],"independent_gnark_exports":proofs,"proof_public_members":proofs*2,"prior_count":7233,"next_prior_count":a["next_prior_count"],"full_stage_executed":full,"new_profiles":if full{3}else{0},"screen_advances":screen["screen_advances_to_full"],"full_gate_passed":a["full_gate_passed"],"closing_pins_checked":protocol["pins"].as_object().unwrap().len(),"adopted":false,"goal_achieved":false,"no_successful_capture_repeated":true});save(r.join("closeout.json"),&close);
 let mut md=String::from("# Combined K/H top-digit reduction\n\n");
 let c=&a["cases"]["1x2-w32"];writeln!(md,"Primary32 paired candidate/accepted ratio: **{:.6}**; candidate/fresh: **{:.6}**. The screen advances: **{}**. Full gate passes: **{}**. No change is adopted; production remains unchanged. There is no minimum positive-gain cutoff.\n",c["pairs"]["combined/accepted"]["geometric_ratio"].as_f64().unwrap(),c["pairs"]["combined/fresh"]["geometric_ratio"].as_f64().unwrap(),screen["screen_advances_to_full"],a["full_gate_passed"]).unwrap();
 md.push_str("The final short digit in fused K/H previously reduced two independent sets of digit buckets and combined their weighted sums. This candidate treats the two borrowed point slices as one indexed input, combining equal-digit buckets before the existing affine reductions. It can share inversion batches and duplicate bucket weighting. It changes arithmetic topology rather than launch ordering. The [previous trace](../2026-10-27-arithmetic-leaves/README.md) showed prompt K/H window starts under instrumentation; it did not establish removable service time or predict this candidate's speed.\n\nOnly `msm.rs` and `msm_affine/fused_kh.rs` change. The indexed reducer is factored through a typed point getter; the original single-slice caller retains its input and tile geometry. The combined top path allocates one existing kind of four-byte index order over the borrowed inputs. It preserves ordinary fused windows, eligibility, positive final digits, complete curve arithmetic, tile size, field kernels, other query paths and runtime policy. There is no new point table, copied input point array, second execution plan, pool or field primitive. Reversing the recorded edits recovers the original files; the other168 originals are exact.\n\n## Verified SDK latency\n\nRyzen9950X. Fresh blinded proving, witness construction, self-verification and serialization are timed; loading and primes are excluded. The exact accepted SDK and the pinned baseline from the preceding fusion study are controls. That baseline is reused unchanged with its source/library/consumer pins rechecked; no new baseline build is claimed. The candidate uses the same native flags, fat LTO, one code-generation unit and standard SDK driver.\n\nTimes are medians of process medians; ratios and microsecond savings pair within rotated/reversed fresh-process blocks. CPU includes coordination; lifetime RSS includes load and primes and is not minimum RAM.\n\n|Case|Accepted ms|Fresh ms|Combined ms|Combined/accepted|Combined/fresh|Paired saving vs fresh µs|Wins vs fresh|Combined RSS MiB|Combined CPU ms/request|\n|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|\n");
 for(name,c)in a["cases"].as_object().unwrap(){let m=&c["modes"];let p=&c["pairs"];writeln!(md,"|{name}|{:.6}|{:.6}|{:.6}|{:.6}|{:.6}|{:.3}|{}|{:.2}|{:.3}|",m["accepted"]["ms"].as_f64().unwrap(),m["fresh"]["ms"].as_f64().unwrap(),m["combined"]["ms"].as_f64().unwrap(),p["combined/accepted"]["geometric_ratio"].as_f64().unwrap(),p["combined/fresh"]["geometric_ratio"].as_f64().unwrap(),p["combined/fresh"]["saving_us"].as_f64().unwrap(),p["combined/fresh"]["wins"],m["combined"]["maxrss_mib"].as_f64().unwrap(),m["combined"]["cpu_ms_per_request"].as_f64().unwrap()).unwrap();}
 md.push_str("\nThe screen uses three blocks, primary16 on CPUs0–15 and primary32 on CPUs0–31, with17 timed requests after3 primes per process. Fresh/accepted must stay within factor1.05 in every block and factor1.03 for paired medians. Primary32 must improve against both controls with at least2/3 block wins, and both cases must stay within2% against both controls. All observations and failures remain included. There are no threshold changes, posthoc selectors or repeated successful captures.\n\n");
 for key in ["calibration_failures","primary_failures","regressions"]{writeln!(md,"{key}: `{}`.\n",a[key]).unwrap();}
 if full {
  md.push_str("The full stage follows the screen with seven blocks over all nine shapes at32 workers plus primary16, followed by three separate warm199Hz cycle profiles after all latency. The full gate also requires original-eight paired geometric improvement/tie against both controls, every-case nonregression, and primary32 improvement with at least4/7 wins.\n\n## Supplied M5 references\n\nThese are historical supplied CPU and Metal values; M5 is not remeasured. No reference was supplied for54→1.\n\n|Shape|Combined ms|M5 CPU ms|CPU speedup|M5 Metal ms|Metal speedup|\n|---|---:|---:|---:|---:|---:|\n");
  for c in a["cases"].as_object().unwrap().values().filter(|c|c["workers"]==32){let ms=c["modes"]["combined"]["ms"].as_f64().unwrap();if let(Some(cpu),Some(metal))=(c["reference"]["cpu_ms"].as_f64(),c["reference"]["metal_ms"].as_f64()){writeln!(md,"|{}|{ms:.6}|{cpu:.0}|{:.3}×|{metal:.0}|{:.3}×|",c["shape"].as_str().unwrap(),cpu/ms,metal/ms).unwrap();}else{writeln!(md,"|{}|{ms:.6}|—|—|—|—|",c["shape"].as_str().unwrap()).unwrap();}}
 }else{assert!(!r.join("performance").exists());md.push_str("The full stage and cycle profiles did not run. The [last complete all-shape SDK matrix](../2026-10-26-pairing-x-chain-sdk/README.md) retains every supplied M5 CPU/Metal comparison and remains authoritative outside this screen.\n\n");}
 md.push_str("## Correctness, memory and limits\n\nAll110 native core tests, two raw tests, six cubic tests, generator and portable/no-IFMA consumer checks pass. The new generator oracle checks independent expected sums and the original separate top reductions for odd K/H lengths, signed and identity bases, zero/one/minus-one/random/mixed/boundary scalars, widths12/13/14 and pools1/4. The existing full fused-query oracle also covers30529+32768 inputs, complete-curve cases and every supported width. Field source and its accepted qualification are inherited unchanged; no new field-suite execution is claimed.\n\nCombining index orders preserves their aggregate four-byte input-entry storage. With the same point tile size, the combined number of tiles cannot exceed the sum of the separate counts. Temporary tree storage and allocator lifetimes still depend on concurrent work; no intrinsic whole-process saving or minimum-RAM guarantee follows from that bound. A passing latency result would still require pressure, resource-policy and compatibility review before adoption.\n\nCandidate preflight covers all nine shapes at four workers: one timed request plus three primes per process,36 SDK requests and nine fresh exports. All measured exports pass independent Gnark verification,164-byte proof length, pinned public binding and freshness against7,233 prior identities plus newly exported proofs. No helper, build, hash, archive or verifier overlaps timed captures.\n\n");
 writeln!(md,"Total **{} SDK requests**, **{} fresh independently verified exports**, **{} proof/public members**; proof ledger **7,233 → {}**. All170 production files and the accepted SDK remain unchanged. The original all-eight CPU10× objective remains active and unproven.\n",a["sdk_requests"],proofs,proofs*2,a["next_prior_count"]).unwrap();
 md.push_str("No new AWS/Aeglos, phone, TEE, giant-circuit, swap, minimum-RAM, memory-pressure, concurrency or throughput qualification is claimed.\n\n");
 for(name,p)in [("reused fresh",r.join("fresh-control-artifacts.json")),("combined",r.join("native/combined/artifacts.json"))]{let b=read(p);writeln!(md,"{name} executable: `{}`; SHA-256 `{}`.\n",b["binary"].as_str().unwrap(),b["binary_sha256"].as_str().unwrap()).unwrap();}
 md.push_str("[Design](artifacts/design.md), [source audit](artifacts/implementation-audit.json), [edits](artifacts/edits.json), [screen analysis](artifacts/screen-analysis.json), [native tests](artifacts/native/core/tests.json), [proof inventory](artifacts/proof-inventory.json), [artifact hashes](artifact-index.json).\n");
 fs::create_dir_all(d).unwrap();fs::write(d.join("README.md"),md).unwrap();fs::copy("/tmp/zopro-grouping-module/production-source-manifest.json",r.join("accepted-source-manifest.json")).unwrap();
 let mut index=BTreeMap::new();archive(r,r,&d.join("artifacts"),&mut index);for(p,h)in &index{assert_eq!(&hash(d.join("artifacts").join(p)),h);}for(p,h)in inventory.as_object().unwrap(){assert_eq!(hash(d.join("artifacts").join(Path::new(p).strip_prefix(r).unwrap())),h.as_str().unwrap());}save(d.join("artifact-index.json"),&json!(index));println!("{}archive hashes;{}proof/public members checked;nextprior{}",index.len(),proofs*2,a["next_prior_count"]);
}
fn archive(root:&Path,here:&Path,dest:&Path,index:&mut BTreeMap<String,String>){let mut paths:Vec<_>=fs::read_dir(here).unwrap().map(|e|e.unwrap().path()).collect();paths.sort();for p in paths{let rel=p.strip_prefix(root).unwrap();let s=rel.display().to_string();if s.starts_with("target-"){continue;}if p.is_dir(){archive(root,&p,dest,index);continue;}if s.starts_with("candidate/")&&!["candidate/crates/zopro-core/src/msm.rs","candidate/crates/zopro-core/src/msm_affine/fused_kh.rs"].contains(&s.as_str()){continue;}if !["json","jsonl","rs","md","txt","log","proof","public"].iter().any(|x|p.extension().is_some_and(|e|e==*x)){continue;}let q=dest.join(rel);fs::create_dir_all(q.parent().unwrap()).unwrap();fs::copy(&p,&q).unwrap();let h=hash(&q);assert_eq!(h,hash(&p));index.insert(s,h);}}
